    if (h >= 65.0 && h <= 150.0 && s >= 0.18 && l >= 0.18 && l <= 0.76) return 2.0;
    // Tiles: terracotta H 0..22 or blue H 185..245, S .24..85, L .24..70.
    if ((h <= 22.0 || (h >= 185.0 && h <= 245.0)) &&
        s >= 0.24 && s <= 0.85 && l >= 0.24 && l <= 0.70) return 5.0;
    // Sand: H 39..65, S .45..85, L .60..84.
    if (h >= 39.0 && h <= 65.0 && s >= 0.45 && s <= 0.85 && l >= 0.60 && l < 0.84) return 1.0;
    // Plaster: warm pale colours, H 24..65, S .12..90, L .76..96.
